package com.projectdark.mobile;
import android.content.Context;import android.graphics.*;import com.projectdark.mobile.world.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import java.util.*;import java.io.*;import java.lang.reflect.*;import org.json.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class MineTownV203Test {
 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();for(String n:new String[]{"project_dark_f5m_v1","project_dark_skill_book_v1","project_dark_skill_test_v1"})c.getSharedPreferences(n,0).edit().clear().commit();F5mSaveStore.install(c);UiTheme.install(c);}
 @SuppressWarnings("unchecked") <T>T field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return(T)f.get(o);}
 Object call(GameView v,String n,Class<?>[] types,Object...args)throws Exception{Method m=GameView.class.getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(v,args);}
 void tick(GameView v,int n)throws Exception{for(int i=0;i<n;i++)call(v,"update",new Class<?>[]{float.class},.05f);}
 void tap(GameView v,float x,float y){TownInteriorTest.tap(v,x,y);}
 void shot(GameView v,String name)throws Exception{Bitmap b=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File f=new File("build/reports/horror-v179/v203/"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream o=new FileOutputStream(f)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,o));}b.recycle();}
 GameView town()throws Exception{GameView v=new GameView(c);v.layout(0,0,960,540);call(v,"travelTown",new Class<?>[]{String.class},MineTownGeometry.ID);return v;}
 void approach(GameView v,String id)throws Exception{RuntimeState s=field(v,"state");WorldRuntimeAdapter w=field(v,WorldDef.ID.equals(s.currentMapId())?"worldAdapter":"poteFieldAdapter");assertTrue("manager path "+id,CampaignNavigationTest.walk(w,w.requestNpcApproach(id)));RuntimeState.Npc npc=s.npcs().stream().filter(n->n.id.equals(id)).findFirst().get();assertEquals(InteractionController.TickResult.DIALOG_OPENED,((InteractionController)field(v,"interaction")).request(s,npc));}
 @Test public void actualMillesManagerDialogTravelsToMineReturnsAndRestoresWithoutProgressGrant()throws Exception{
  GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=field(v,"state");long exp=CampaignProgress.earnedExp(s.rpg()),gold=s.rpg().gold();String quests=s.rpg().campaign().snapshot().getJSONArray("complete").toString();Map<String,Integer> inv=new LinkedHashMap<>(s.rpg().inventory());
  approach(v,"pote_travel_guide");RectF card=TownTravelWindow.cardFor(WorldDef.ID,MineTownGeometry.ID);assertNotNull(card);shot(v,"milles-mine-travel-card");tap(v,card.centerX(),card.centerY());assertEquals(MineTownGeometry.ID,s.currentMapId());assertEquals(exp,CampaignProgress.earnedExp(s.rpg()));assertEquals(gold,s.rpg().gold().longValue());assertEquals(inv,s.rpg().inventory());assertEquals(quests,s.rpg().campaign().snapshot().getJSONArray("complete").toString());assertTrue(s.monsters().isEmpty());shot(v,"mine-arrival");assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView resumed=new GameView(c);resumed.layout(0,0,960,540);RuntimeState r=field(resumed,"state");assertEquals(MineTownGeometry.ID,r.currentMapId());assertEquals(s.player().x,r.player().x,0);assertEquals(s.player().y,r.player().y,0);approach(resumed,"mine_town_travel");card=TownTravelWindow.cardFor(MineTownGeometry.ID,WorldDef.ID);tap(resumed,card.centerX(),card.centerY());assertEquals(WorldDef.ID,r.currentMapId());assertEquals(gold,r.rpg().gold().longValue());
 }
 @Test public void bothActualDoorRoutesUseExistingServicesExitToMineAndPersistInside()throws Exception{
  for(MineTownGeometry.Building b:MineTownGeometry.BUILDINGS){reset();GameView v=town();RuntimeState s=field(v,"state");s.rpg().restoreGold(5000);WorldRuntimeAdapter w=field(v,"poteFieldAdapter");assertTrue("door route "+b.title,CampaignNavigationTest.walk(w,w.requestGroundWorld(b.doorX(),b.doorY())));w.tickNavigation(.7f);assertTrue((Boolean)call(v,"checkCampaignGate",new Class<?>[]{}));assertEquals(b.interior,s.currentMapId());TownInteriorDef d=TownInteriorDef.forMap(b.interior);assertTrue(d.isRegional());assertEquals(1,s.npcs().size());assertTrue(s.monsters().isEmpty());shot(v,b.interior+"-room");assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView resumed=new GameView(c);resumed.layout(0,0,960,540);RuntimeState r=field(resumed,"state");assertEquals(b.interior,r.currentMapId());WorldRuntimeAdapter room=field(resumed,"reagentShopAdapter");
   WorldCameraTransform.Point npc=room.worldToScreen(d.npcX(),d.npcY());tap(resumed,npc.x,npc.y-24);
   if(d.kind==TownInteriorDef.Kind.INN){tick(resumed,400);assertTrue((Boolean)field(resumed,"innDialogueOpen"));long money=r.rpg().gold();r.player().hp=1;r.player().mp=1;shot(resumed,"mine-inn-rest-dialog");tap(resumed,560,425);assertEquals(money-50,r.rpg().gold().longValue());assertEquals(r.player().maxHp,r.player().hp);assertEquals(r.player().maxMp,r.player().mp);}
   else{assertTrue(((TownShopWindow)field(resumed,"townWindow")).isOpen());long money=r.rpg().gold();shot(resumed,"mine-reagent-shop-ui");tap(resumed,780,387);assertEquals(money,r.rpg().gold().longValue());tap(resumed,586,305);assertTrue(r.rpg().gold()<money);tap(resumed,895,76);}
   room.requestGroundWorld(d.exitX(),d.exitY());tick(resumed,600);assertEquals(MineTownGeometry.ID,r.currentMapId());assertNull(MineTownGeometry.doorAt(r.player().x,r.player().y));assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView saved=new GameView(c);assertEquals(MineTownGeometry.ID,((RuntimeState)field(saved,"state")).currentMapId());
  }
 }
 @Test public void terrainGraphConnectsBothServicesBridgesAndMineButBlocksWaterWallsAndRailings()throws Exception{
  List<WorldMoveTargetController.TileCenter> connected=CampaignWorld.connectedTiles(MineTownGeometry.ID);assertTrue(connected.size()>1200);Set<String> all=new HashSet<>();for(WorldMoveTargetController.TileCenter t:connected)all.add(Math.round(t.x)+","+Math.round(t.y));
  for(MineTownGeometry.Building b:MineTownGeometry.BUILDINGS){assertTrue(all.contains(Math.round(b.doorX())+","+Math.round(b.doorY())));assertTrue(all.contains(Math.round(b.returnX())+","+Math.round(b.returnY())));assertTrue(MineTownGeometry.blocked(b.u,b.v-2));}
  assertTrue(MineTownGeometry.blocked(35,32));assertTrue(MineTownGeometry.blocked(19,32));assertTrue(MineTownGeometry.blocked(43,32));assertFalse(MineTownGeometry.blocked(21,32));assertFalse(MineTownGeometry.blocked(45,32));assertTrue(all.contains(Math.round(MineTownGeometry.x(21,32))+","+Math.round(MineTownGeometry.y(21,32))));assertTrue(all.contains(Math.round(MineTownGeometry.x(45,32))+","+Math.round(MineTownGeometry.y(45,32))));assertTrue(MineTownGeometry.blocked(14,23));
  GameView v=town();RuntimeState s=field(v,"state");WorldRuntimeAdapter w=field(v,"poteFieldAdapter");for(int[] uv:new int[][]{{21,32},{45,32},{16,24}})assertTrue(CampaignNavigationTest.walk(w,w.requestGroundWorld(MineTownGeometry.x(uv[0],uv[1]),MineTownGeometry.y(uv[0],uv[1]))));assertEquals(.60f,w.tileStepSeconds(),0);assertTrue(s.monsters().isEmpty());
 }
 @Test public void sourceAssetsAndNativeLandmarksRenderAtStandardAndWideViews()throws Exception{
  GameView v=town();RuntimeState s=field(v,"state");WorldRuntimeAdapter w=field(v,"poteFieldAdapter");for(int[] uv:new int[][]{{42,23},{42,50},{21,32},{16,24}}){WorldMoveTargetController.TileCenter t=CampaignWorld.nearestConnectedTile(MineTownGeometry.ID,MineTownGeometry.x(uv[0],uv[1]),MineTownGeometry.y(uv[0],uv[1]));s.player().x=t.x;s.player().y=t.y;w.snapCameraToPlayer();shot(v,"landmark-"+uv[0]+"-"+uv[1]);}
  v.layout(0,0,1280,540);shot(v,"mine-wide");String label=(String)call(v,"currentMapLocation",new Class<?>[]{});assertTrue(label.startsWith("마인 마을 ("));assertEquals(2,TownServiceLabels.signs(MineTownGeometry.ID).size());assertEquals(2,TownInteriorDef.MINE.size());
 }
 @Test public void allTravelCardsRemainInsideModalAndHaveUniqueHitTargets(){for(TownTravel.Destination town:TownTravel.TOWNS){List<String> ds=TownTravelWindow.destinations(town.map);for(String id:ds){RectF a=TownTravelWindow.cardFor(town.map,id);assertTrue(TownTravelWindow.PANEL.contains(a.left,a.top));assertTrue(TownTravelWindow.PANEL.contains(a.right,a.bottom));assertEquals(id,TownTravelWindow.hit(town.map,a.centerX(),a.centerY()));for(String other:ds)if(!other.equals(id))assertFalse(RectF.intersects(a,TownTravelWindow.cardFor(town.map,other)));}}}
 @Test public void twelveRoundTripsKeepFloorBoundedAndStaticWarmFramesDoNotRebuild()throws Exception{
  GameView v=town();MineTownRenderer renderer=field(v,"mineTownRenderer");for(int i=0;i<12;i++){call(v,"travelTown",new Class<?>[]{String.class},MineTownGeometry.ID);Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));int count=renderer.floorBuildCount();v.draw(new Canvas(b));assertEquals(count,renderer.floorBuildCount());assertTrue(renderer.floorCacheEntries()<=32);assertTrue(renderer.floorCachePixelBytes()<=8652800L);b.recycle();call(v,"travelTown",new Class<?>[]{String.class},WorldDef.ID);assertEquals(0,renderer.floorCacheEntries());}
 }
}
